"""Regenerate all plots from saved CSVs/JSON without re-running experiments."""
import csv
from pathlib import Path

from . import run_experiment as exp

CODE_DIR = Path.cwd()
RESULTS = CODE_DIR / "results"


def _read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def load_sim():
    rows = _read_csv(RESULTS / "sim_results.csv")
    eff  = _read_csv(RESULTS / "sim_efficiency.csv")
    eff_by_name = {r["Method"]: r for r in eff}

    results = {"n_labeled": [int(r["n_labeled"]) for r in rows]}
    for m in exp.SIM_METHODS:
        d = exp.DISPLAY[m]
        auc_row = eff_by_name.get(d, {})
        results[m] = {
            "mean":     [float(r[f"{d}_mean"])     for r in rows],
            "std":      [float(r[f"{d}_std"])      for r in rows],
            "cov_mean": [float(r[f"{d}_cov_mean"]) for r in rows],
            "cov_std":  [float(r[f"{d}_cov_std"])  for r in rows],
            "ns_mean":  [float(r[f"{d}_ns_mean"])  for r in rows],
            "ns_std":   [float(r[f"{d}_ns_std"])   for r in rows],
            "cov_auc":  float(auc_row.get("Cov AUC", 0)),
            "auc":      float(auc_row.get("AUC", 0)),
        }
    return results


def load_llm():
    rows = _read_csv(RESULTS / "llm_results.csv")
    metric_keys = ["semantic_score", "non_seed_score", "table_match", "column_coverage"]
    results = {"n_labeled": [int(r["n_labeled"]) for r in rows]}
    for m in exp.LLM_METHODS:
        d = exp.DISPLAY[m]
        results[m] = [
            {mk: float(r[f"{d}_{mk}"]) for mk in metric_keys}
            for r in rows
        ]
    return results


def load_gp_pred():
    rows = _read_csv(RESULTS / "gp_pred_results.csv")
    results = {"n_labeled": [int(r["n_labeled"]) for r in rows]}
    for m in exp.GP_PRED_METHODS:
        d = exp.DISPLAY[m]
        results[m] = {
            "rmse": [float(r[f"{d}_rmse"]) for r in rows],
            "mse":  [float(r[f"{d}_mse"])  for r in rows],
        }
    return results


def load_realistic():
    rows = _read_csv(RESULTS / "realistic_results.csv")
    metric_keys = ["semantic_score", "non_seed_score", "table_match", "column_coverage"]
    results = {"n_labeled": [int(r["n_labeled"]) for r in rows]}
    for m in exp.REALISTIC_METHODS:
        d = exp.DISPLAY[m]
        results[m] = [
            {mk: float(r[f"{d}_{mk}"]) for mk in metric_keys}
            for r in rows
        ]
    return results


def main():
    print("Regenerating plots from saved results...")
    exp.plot_sim(load_sim())
    exp.plot_gp_pred(load_gp_pred())
    exp.plot_llm(load_llm())
    exp.plot_realistic(load_realistic())
    print("Done.")


if __name__ == "__main__":
    main()
